import unittest

from calendar_utils import days_in_month, is_leap_year


class TestLeapYears(unittest.TestCase):
    def test_year_2000_is_leap(self):
        self.assertTrue(is_leap_year(2000))

    def test_feb_2000_has_29_days(self):
        self.assertEqual(days_in_month(2000, 2), 29)

    def test_1900_still_not_leap(self):
        self.assertFalse(is_leap_year(1900))
